package com.wizzadrds.theworldremembers; import com.wizzadrds.theworldremembers.home.*; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes; import net.minecraft.world.level.block.Blocks; public final class Phase4HomeStorageGameTest{@GameTest public void homeLinksRealContainer(GameTestHelper c){c.setBlock(3,1,3,Blocks.CHEST);var v=c.spawn(EntityTypes.VILLAGER,4,1,4);c.runAtTickTime(2,()->{TheWorldRemembers.processWorld(c.getLevel());var h=NpcHomeManager.get(c.getLevel()).get(v.getUUID());var s=NpcHomeStorageManager.get(c.getLevel().getServer()).get(v.getUUID());if(h==null){c.fail("Home missing");return;}if(s==null){c.fail("Real container was not linked to home");return;}c.succeed();});}}